	sections = {
		{
			title = "Summary",
			text = [=[The City of Dalaran stands again on the western shore of {red:lordamere-lake}Lordamere Lake{/red}, at the foot of the {link:alterac-mountains}Alterac Mountains{/link}. Its violet spires rise over new walls and bright streets, its banks and inns are open, and its magi walk once more among merchants, craftsmen and guests from far lands. For years the city hid behind a great dome of light while its wizards rebuilt it. That barrier has fallen. The world can see {link:dalaran}Dalaran{/link} again, and Dalaran must now answer to the world.]=],
		},
		{
			title = "Origins",
			text = [=[The story of {link:dalaran}Dalaran{/link}, first of the free cities of {link:arathor}Arathor{/link} and home of the {link:kirin-tor}Kirin Tor{/link}, is told in its own chronicle. In the {link:third-war}Third War{/link}, the {link:scourge}Scourge{/link} came to its gates and took the spellbook of {link:medivh}Medivh{/link}, and {link:archimonde}Archimonde{/link} broke the city with a single spell. The surviving magi returned to the ruins. They raised a vast magical dome over the heart of their city, and behind it they set to work. Outside, the patrols of Dalaran's wizards and their bound elementals guarded the ruined outskirts, and few who came near were welcome.]=],
		},
		{
			title = "The Present Day",
			text = [=[The work is done, or nearly so. No one outside the {link:kirin-tor}Kirin Tor{/link} can yet say why the barrier came down. The city is open, but it is not at peace. Enchantments go astray, arcane constructs slip their bonds, and demonic energy has been felt in its streets. Investigators of the Kirin Tor speak in low voices of a disturbance that grows worse by the day, and they have been ordered to keep the citizens calm. The Kirin Tor now count themselves among the nations of the {link:alliance}Alliance{/link}. The {link:horde}Horde{/link} is not welcome here, and the guards of the city treat its people as enemies. New friends have come instead: the {link:high-order}High Order{/link} of the {link:skyborne}Skyborne{/link}, whose skycutter ships sail between {link:dalaran}Dalaran{/link} and {link:zephras-isle}Zephras Isle{/link} across the planes.]=],
		},
		{
			title = "Inhabitants",
			text = [=[• {b}The {link:kirin-tor}Kirin Tor{/link}.{/b} Archmagi, archivists, arcanists and investigators, the masters of the city.
• {b}The guards of {link:dalaran}Dalaran{/link}.{/b} Kirin Tor guards and enforcers, and arcane sentries that keep watch on their own.
• {b}Citizens and traders.{/b} Bankers, innkeepers, smiths, tailors, jewelers and a toymaker, and an orphanage with its matron.
• {b}The {link:skyborne}Skyborne{/link}.{/b} Mages of the {link:high-order}High Order{/link}, who arrive at the city's skycutter dock.
• {b}Visitors.{/b} Among them a teacher of druids and a Highborne who has come from afar.]=],
		},
		{
			title = "History",
			text = [=[• {b}The Founding.{/b} {link:dalaran}Dalaran{/link} was the first city of {link:arathor}Arathor{/link} to rule itself, and its magi founded the {link:kirin-tor}Kirin Tor{/link}.
• {b}The Fall.{/b} In the {link:third-war}Third War{/link} the city was destroyed.
• {b}The Barrier.{/b} The magi rebuilt Dalaran behind a dome that kept the world out.
• {b}The Present Day.{/b} The barrier is gone, and the city has opened its gates to its allies.]=],
		},
		{
			title = "Lore of the City",
			text = [=[• Wizards of {link:dalaran}Dalaran{/link} now watch the roads of the north. In {link:silverpine-forest}Silverpine{/link} they say they have done so ever since the barrier came down.
• The archmage {link:archmage-ansirem-runeweaver}Ansirem Runeweaver{/link} once wrote a tome on the legends of the Gurubashi trolls. His daughter, to his sorrow, became a pirate.
• The {link:kirin-tor}Kirin Tor{/link} keep a portal for the {link:high-order}High Order{/link}, so that its young mages can reach {link:stormwind-city}Stormwind{/link} and meet the regent there.]=],
		},
	},
})

